CREATE TEMPORARY VIEW dws_instant_filter_click_imp_${grass_region_without_quote} AS
SELECT
    experiment_id
    ,b.exp_group_id AS exp_group_id
    ,COUNT(DISTINCT IF(operation = 'click', a.user_id, NULL)) AS instant_filter_uu
    ,COUNT(IF(operation = 'click', 1, NULL)) AS instant_filter_using_cnt
    ,COUNT(DISTINCT IF(operation = 'impression', a.user_id, NULL)) AS instant_filter_imp_uu
    ,COUNT(IF(operation = 'impression', 1, NULL)) AS instant_filter_imp_cnt
FROM
    srdi_mart.dwd_sr_data_warehouse_search a
JOIN
    user_exp_mapping_${grass_region_without_quote} b
ON
    a.user_id = b.user_id
WHERE
    grass_region = ${grass_region}
    AND local_date = ${local_date}
    AND a.user_id > 0
    AND ((
        operation = 'click'
        AND original_operation = 'action_filter'
        AND page_type IN ('global_search', 'search_in_pdp', 'search_prefill')
        AND page_section IS NULL
        AND target_type IS NULL
    ) OR (
        page_type IN ('global_search', 'search_in_pdp', 'search_prefill')
        AND page_section[0] = 'search_filter_shortcut_bar'
        AND target_type = 'filter_button'
        AND operation = 'impression'
    ))
    AND EXISTS(TRANSFORM(search_filter_string, x -> FROM_JSON(x, 'STRUCT<filter_name:STRING>'))
        ,x -> LOWER(x.filter_name) IN ('instant_delivery', 'fast_delivery')
    )
GROUP BY
    1,2;

