CREATE TEMPORARY VIEW dwd_direct_broad_search_volume_${grass_region_without_quote} AS
SELECT
    CASE
        WHEN EXISTS(TRANSFORM(search_filter_string, x -> FROM_JSON(x, 'STRUCT<filter_name:STRING>'))
            ,x -> LOWER(x.filter_name) IN ('instant_delivery', 'fast_delivery')
        ) THEN 'true'
        ELSE 'false'
    END AS use_instant_filter_type
    ,COALESCE(CAST(layout_type AS STRING), '2') AS layout_type
    ,user_id
    ,device_id
    ,keyword
    ,page_section
    ,target_type
FROM
    srdi_mart.dwd_sr_data_warehouse_search
WHERE
    grass_region = ${grass_region}
    AND local_date = ${local_date}
    ANd user_id > 0
    AND page_type IN ('global_search','search_in_pdp','search_prefill')
    AND (
        (target_type IN ('item','video','livestream', 'curated_search', 'live_stream_floating_preview') AND page_section IS NULL)
        OR ((target_type LIKE 'shop%' OR target_type LIKE 'creator%') AND page_section IS NULL)
        OR (page_section[0] = 'creator')
    )
    AND operation = 'click';

