    ,IF(layout_type IS NOT NULL, layout_type, '__ALL__') AS layout_type 
    ,COUNT(DISTINCT IF(page_section IS NULL AND target_type IN ('item','video','livestream'), (a.user_id, device_id, keyword), NULL)) AS direct_search_success_volume
    ,COUNT(DISTINCT (a.user_id, device_id, keyword)) AS broad_search_success_volume
