CREATE TEMPORARY VIEW dwd_click_imp_order_metrics_${grass_region_without_quote} AS
SELECT
    user_id
    ,device_id
    ,keyword
    ,CASE WHEN EXISTS(TRANSFORM(search_filter_string, x -> FROM_JSON(x, 'STRUCT<filter_name:STRING>'))
        ,x -> LOWER(x.filter_name) IN ('instant_delivery', 'fast_delivery'))
    THEN 'true' ELSE 'false' END AS use_instant_filter_type
    ,COALESCE(CAST(layout_type AS STRING), '2') AS layout_type
    ,target_type AS card_type
    ,IF(SIZE(shop_layout_item_list) < 3, 1, NULL) AS has_empty_shop_layout_item
    ,operation_cnt
    ,place_order_gmv
    ,operation
    ,order_id
FROM
    srdi_mart.dwd_sr_data_warehouse_search
WHERE
    grass_region = ${grass_region}
    AND local_date = ${local_date}
    AND user_id > 0
    AND page_type IN ('global_search','search_in_pdp','search_prefill')
    AND (
        (page_section IS NULL AND target_type IN ('item', 'video', 'livestream'))
        OR (page_section[0] = 'results' AND target_type = 'shop')
    )
    AND operation IN ('impression', 'click', 'order')
UNION ALL
SELECT
    user_id
    ,device_id
    ,source1_keyword AS keyword
    ,CASE WHEN EXISTS(TRANSFORM(source1_search_filter_string, x -> FROM_JSON(x, 'STRUCT<filter_name:STRING>'))
        ,x -> LOWER(x.filter_name) IN ('instant_delivery', 'fast_delivery'))
    THEN 'true' ELSE 'false' END AS use_instant_filter_type
    ,COALESCE(CAST(source1_layout_type AS STRING), '2') AS layout_type
    ,source1_target_type AS card_type
    ,NULL AS has_empty_shop_layout_item
    ,operation_cnt
    ,place_order_gmv
    ,operation
    ,order_id
FROM
    srdi_mart.dwd_sr_data_warehouse_search
WHERE
    grass_region = ${grass_region}
    AND local_date = ${local_date}
    AND user_id > 0
    AND source1_page_type IN ('global_search','search_in_pdp','search_prefill')
    AND (
        (source1_page_section IS NULL AND source1_target_type IN ('item', 'video', 'livestream'))
        OR (source1_page_section[0] = 'results' AND source1_target_type = 'shop')
    )
    AND operation = 'order'
UNION ALL
SELECT
    user_id
    ,device_id
    ,source2_keyword AS keyword
    ,CASE WHEN EXISTS(TRANSFORM(source2_search_filter_string, x -> FROM_JSON(x, 'STRUCT<filter_name:STRING>'))
        ,x -> LOWER(x.filter_name) IN ('instant_delivery', 'fast_delivery'))
    THEN 'true' ELSE 'false' END AS use_instant_filter_type
    ,COALESCE(CAST(source2_layout_type AS STRING), '2') AS layout_type
    ,source2_target_type AS card_type
    ,NULL AS has_empty_shop_layout_item
    ,operation_cnt
    ,place_order_gmv
    ,operation
    ,order_id
FROM
    srdi_mart.dwd_sr_data_warehouse_search
WHERE
    grass_region = ${grass_region}
    AND local_date = ${local_date}
    AND user_id > 0
    AND source2_page_type IN ('global_search','search_in_pdp','search_prefill')
    AND (
        (source2_page_section IS NULL AND source2_target_type IN ('item', 'video', 'livestream'))
        OR (source2_page_section[0] = 'results' AND source2_target_type = 'shop')
    )
    AND operation = 'order';

--sql_divide_splitter--

CREATE TEMPORARY VIEW dws_click_imp_order_other_metrics_${grass_region_without_quote} AS
SELECT
    experiment_id
    ,exp_group_id
    ,IF(GROUPING(use_instant_filter_type) = 1, '__ALL__', use_instant_filter_type) AS use_instant_filter_type
    ,IF(GROUPING(layout_type) = 1, '__ALL__', layout_type) AS layout_type
    ,IF(GROUPING(card_type) = 1, '__ALL__', card_type) AS card_type
    ,SUM(IF(operation = 'impression', operation_cnt, NULL)) AS imp_cnt
    ,COUNT(DISTINCT IF(operation = 'impression', a.user_id, NULL)) AS imp_uu
    ,SUM(IF(operation = 'click', operation_cnt, NULL)) AS click_cnt
    ,COUNT(DISTINCT IF(operation = 'click', a.user_id, NULL)) AS click_uu
    ,SUM(IF(operation = 'order' AND operation_cnt > 0, operation_cnt, NULL)) AS order_cnt
    ,COUNT(DISTINCT IF(operation = 'order' AND operation_cnt > 0, a.user_id, NULL)) AS order_uu
    ,SUM(IF(operation = 'order' AND operation_cnt > 0, place_order_gmv, NULL)) AS gmv
    ,CASE
        WHEN layout_type = '3'
        THEN COUNT(DISTINCT IF(operation = 'impression', (a.user_id, device_id, keyword), NULL))
        ELSE NULL
    END AS shop_search_volume
    ,CASE
        WHEN layout_type = '3' AND card_type = 'shop'
        THEN SUM(IF(operation = 'impression', has_empty_shop_layout_item, NULL))
        ELSE NULL
    END AS empty_shop_imp_cnt
FROM
    dwd_click_imp_order_metrics_${grass_region_without_quote} a
JOIN
    user_exp_mapping_${grass_region_without_quote} b
ON
    a.user_id = b.user_id
GROUP BY
    experiment_id
    ,exp_group_id
    ,CUBE(use_instant_filter_type, layout_type, card_type);

--sql_divide_splitter--

CREATE TEMPORARY VIEW dws_shop_item_fill_rate_${grass_region_without_quote} AS
SELECT
    experiment_id
    ,exp_group_id
    ,use_instant_filter_type
    ,CAST(SUM(IF(card_type = 'item', imp_cnt, NULL)) AS DOUBLE) / (SUM(IF(card_type = 'shop', imp_cnt, NULL)) * 3.0) AS shop_item_fill_rate
FROM
    dws_click_imp_order_other_metrics_${grass_region_without_quote}
WHERE
    layout_type = '3'
GROUP BY
    1,2,3;

--sql_divide_splitter--

