CREATE TEMPORARY VIEW dwm_ads_revenue_${grass_region_without_quote} AS
SELECT
-- joining columns on both tables must be unique pairs in each table to avoid overcounting
    user_id
    ,COALESCE(layout_type, '2') AS layout_type
    ,COALESCE(use_instant_filter_type, 'false') AS use_instant_filter_type
    ,ads_rev
