CREATE TEMPORARY VIEW dws_ads_revenue_${grass_region_without_quote} AS
SELECT
    experiment_id
    ,exp_group_id
    ,IF(use_instant_filter_type IS NOT NULL, use_instant_filter_type, '__ALL__') AS use_instant_filter_type
    ,IF(layout_type IS NOT NULL, layout_type, '__ALL__') AS layout_type
    ,SUM(ads_rev) AS ads_rev
