CREATE TEMPORARY VIEW global_search_and_platform_metrics_${grass_region_without_quote} AS
SELECT
    experiment_id
    ,exp_group_id
    ,SUM(CASE WHEN
            (reporting_business_line = 'Search' AND reporting_module = 'Global Search')
            OR (source1_reporting_business_line = 'Search' AND source1_reporting_module = 'Global Search')
            OR (source2_reporting_business_line = 'Search' AND source2_reporting_module = 'Global Search')
        THEN operation_cnt ELSE NULL
    END) AS global_search_order_cnt
    ,SUM(CASE WHEN
            (reporting_business_line = 'Search' AND reporting_module = 'Global Search')
            OR (source1_reporting_business_line = 'Search' AND source1_reporting_module = 'Global Search')
            OR (source2_reporting_business_line = 'Search' AND source2_reporting_module = 'Global Search')
        THEN place_order_gmv ELSE NULL
    END) AS global_search_gmv
    ,SUM(operation_cnt) AS platform_order_cnt
    ,SUM(place_order_gmv) AS platform_gmv
FROM
    srdi_mart.dwd_sr_data_warehouse_platform a
JOIN
    user_exp_mapping_${grass_region_without_quote} b
ON
    a.user_id = b.user_id
WHERE
    grass_region = ${grass_region}
    AND local_date = ${local_date}
    AND operation = 'order'
GROUP BY
    1,2;

