INSERT OVERWRITE TABLE ${schema}.dws_sr_data_warehouse_search_abtest_srp_layout_instant_filter_metrics_1d
PARTITION (
    grass_region = ${grass_region}
    ,local_date = ${local_date}
)
SELECT
    a.experiment_id
    ,a.exp_group_id
    ,a.use_instant_filter_type
    ,a.layout_type

    ,group_uu
    ,search_uu
    ,search_volume
    ,instant_filter_uu
    ,instant_filter_using_cnt
    ,no_results_cnt
    ,no_results_volume
    ,instant_filter_no_results_cnt
    ,instant_filter_no_results_volume

    ,direct_search_success_volume
    ,broad_search_success_volume
    ,imp_cnt
    ,imp_uu
    ,click_cnt
    ,click_uu
    ,order_cnt
    ,order_uu
    ,gmv
    ,avg_edt
    ,ads_rev

    ,card_type
    ,instant_filter_imp_uu
    ,instant_filter_imp_cnt
    ,shop_search_volume
    ,empty_shop_imp_cnt
    ,shop_item_fill_rate
    ,global_search_order_cnt
    ,global_search_gmv
    ,platform_order_cnt
    ,platform_gmv
FROM
    dws_main_metrics_${grass_region_without_quote} a
LEFT JOIN
    exp_group_uu_${grass_region_without_quote} b
ON
    a.experiment_id = b.experiment_id
    AND a.exp_group_id = b.exp_group_id
